def find_best_charging_station(instance, route):
    best_station = None
    min_energy_shortage = float('inf')
    for station_id in instance.station_ids:
        new_route = route[:1] + [station_id] + route[1:]
        states = propagate_route(instance, new_route)
        if all(state.battery_arrival >= 0 for state in states):
            energy_shortage = sum(max(0, -state.battery_arrival) for state in states)
            if energy_shortage < min_energy_shortage:
                min_energy_shortage = energy_shortage
                best_station = station_id
    return best_station

def handle_window_fault(instance, route):
    states = propagate_route(instance, route)
    for state in states:
        node = instance.node_map[state.node_id]
        if state.service_start > node.due_time:
            # Attempt to insert a charging station to fix the window fault
